#!/usr/bin/env bash
# Writes .termfold/signing.properties (gitignored). Survives future Cursor sessions on this clone.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
mkdir -p "$ROOT/.termfold"
OUT="$ROOT/.termfold/signing.properties"

STORE="${TERMFOLD_STORE_PASSWORD:-${1:-}}"
KEY="${TERMFOLD_KEY_PASSWORD:-${2:-$STORE}}"

if [[ -z "$STORE" ]]; then
  echo "Usage: TERMFOLD_STORE_PASSWORD=... [TERMFOLD_KEY_PASSWORD=...] $0"
  echo "   or: $0 <storePassword> [keyPassword]"
  exit 1
fi

umask 077
cat > "$OUT" <<EOF
# Generated by tools/save-signing-config.sh — do not commit
termfold.storePassword=$STORE
termfold.keyPassword=$KEY
EOF
echo "Saved signing passwords to $OUT (mode 600)"
echo "Next: put keystore at $ROOT/.termfold/termfold-release.jks then bash tools/build-production-apk.sh"
